      WAV.text(ctx, 'tension at height y is the weight below it: T = μgy, so v = √(gy)', s.w / 2, s.h - 10, { size: 11, color: th.ink3, weight: 700 });
      outA(el < ttop ? 'climbing' : 'reached the top', 'pulse sent up from the bottom');
